import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Play, X } from 'lucide-react';

const experiences = [
  {
    title: "Marsad – Headless OMS & ERP Platform",
    description: "Architected and developed a headless Order Management System (OMS) with ERP dashboards for UAE businesses. Implemented a custom WordPress plugin to expose a bespoke Menu REST API endpoint, decoupled from native WordPress menus, enabling optimized data structures for frontend consumption. Integrated WooCommerce APIs for real-time order, product, and category synchronization, and built scalable UI components with advanced filtering, pagination, and role-based access.",
    video: "/videos/marsad.mov"
  },
  {
    title: "SwapXe – Authenticated Crypto Dashboard",
    description: "Designed and implemented a secure crypto dashboard with JWT-based authentication and route-level access control. Integrated multiple REST APIs to display real-time wallet balances, transaction history, and analytics. Focused on secure token handling, API error resilience, and responsive dashboard layouts optimized for both desktop and mobile environments.",
    video: "/videos/swapxe.mov"
  },
  {
    title: "Aviation ERP System",
    description: "Contributed to an enterprise-grade aviation ERP system supporting spare parts management, RFQ workflows, vendor coordination, and sales documentation. Designed normalized relational data models and implemented paginated A4 PDF reporting for operational and audit use cases, ensuring data integrity and domain-specific accuracy.",
    video: "/videos/aviation_erp.mov"
  },
  {
    title: "Crypto Exchange – Real-Time Quote & Swap API Layer",
    description: "Built backend services integrating multiple crypto pricing and swap providers to deliver real-time exchange quotes. Implemented rate refresh strategies, provider comparison logic, and graceful degradation handling for API outages, ensuring accurate and performant quote delivery.",
    video: "/videos/blockchain.mov"
  },
  {
    title: "Job Application Automation Platform with Live Monitoring",
    description: "Developed a full-stack job application automation platform using browser automation. Implemented a live bot-run monitoring system displaying real-time execution state, step-level logs, and application outcomes. Enforced sequential application logic to ensure each job completes fully before progression, simulating realistic human interaction patterns.",
    video: "/videos/jobbot.mov"
  },

];

export default function JobExperience() {
  const [selectedVideo, setSelectedVideo] = useState(null);

  useEffect(() => {
    if (selectedVideo) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [selectedVideo]);

  // Handle ESC key
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === 'Escape') setSelectedVideo(null);
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  return (
    <motion.section
      id="job-experience"
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.9 }}
      className="py-20 bg-white dark:bg-gray-900 rounded-xl shadow-lg"
    >
      <h2 className="text-3xl font-bold text-center mb-12 text-gray-900 dark:text-white">
        Vedio 
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-6">
        {experiences.map((exp, index) => (
          <motion.div
            key={index}
            whileHover={{ scale: 1.02 }}
            className="flex flex-col bg-gradient-to-b from-gray-100 to-gray-200 dark:from-gray-800 dark:to-gray-900 rounded-2xl p-6 shadow-md"
          >
            <h3 className="text-xl font-bold mb-4 text-gray-900 dark:text-white min-h-[56px]">
              {exp.title}
            </h3>
            <p className="text-sm text-gray-700 dark:text-gray-300 mb-6 flex-grow">
              {exp.description}
            </p>
            <button
              onClick={() => setSelectedVideo(exp.video)}
              className="mt-auto flex items-center justify-center gap-2 w-full py-3 rounded-xl font-medium
                bg-gray-900 text-white hover:bg-gray-800
                dark:bg-white dark:text-gray-900 dark:hover:bg-gray-200
                transition-all duration-300 shadow-sm"
            >
              <Play className="w-4 h-4 fill-current" />
              Watch Demo
            </button>
          </motion.div>
        ))}
      </div>

      <AnimatePresence>
        {selectedVideo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
            onClick={() => setSelectedVideo(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="relative w-full max-w-5xl bg-black rounded-2xl overflow-hidden shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setSelectedVideo(null)}
                className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 text-white rounded-full transition-colors z-10"
              >
                <X className="w-6 h-6" />
              </button>

              <video
                src={selectedVideo}
                controls
                autoPlay
                className="w-full h-auto max-h-[80vh] object-contain"
              >
                Your browser does not support the video tag.
              </video>

              <div className="p-4 bg-gray-900 text-center">
                <p className="text-sm text-gray-400">
                  If the video does not play, an MP4 version will be provided.
                </p>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.section>
  );
}
